INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1052552-ise303', 'stk-user3193', 'ISE 303', 'info', '{"desc": "Operation Research يعتبر من اهم مجالات الهندسة الصناعية وراح تدرس ايضا كورس مكمل للـ 303 وهو كورس الـ 421\n\nكورس متوسط يميل للسهولة في بعض الموضوعات وللصعوبة في اخرى\n\nانا اعشق الكورسات الي تهتم بالمنطق الرياضي والتحليل لذلك اجد انها مادة محببة لي\n\nالكورس هذا انا اعتبر الاسئلة الي فيه الغاز والواحد يحاول يجد الحل\n\nالكورس يعلمك كيف تحصل على الحل المثالي من بين جميع الحلول\n\nراح تدرس التالي:\n\nModeling\n\nوراح تدرس فيها كيف تحلل المشكلة و طريقة كتابتها على شكل معادلات وليس مطلوب منك ان تجد الحل في هذه المرحلة فقط المطلوب انك تصيغ المشكلة على شكل معادلات\n\nمثال:\n\nانت تملك مخطط مساحتة 40 الف متر مربع و تريد ان تبني نوعين من المباني\n\nمبنى بدور واحد بمساحة 400 متر مربع\nمبنى بدورين بمساحة 500 متر مربع\n\nبحيث:\nان مجموع مساحة المباني لا يزيد عن 35 الف متر مربع\nان مجموع المباني بدورين تكون ضعف او اكثر مجموع المباني بدور\n\nفالمطلوب منك في هذه المرحلة ان تصيغ المشكلة على شكل معادلات , مثلا\n\nلنقل ان\ny = عدد المباني بدورين\nx = عدد المباني بدور واحد\n\nراح تدرس ايضا simplex method وهي اداة لإيجاد الحل الانسب لمشكلة معينة مربوطة باكثر من عنصر المثال السابق فقط عندنا عنصرين وهما x and y لكن في السمبلكس راح تحل مثلا x ,y,m,n,d and f وتوجد الحل الامثل لكل عنصر وهي اداة رائعة ومهمة جدا ايضا وبنفس الوقت تحتاج لجهد وتركيز مع حل الكثير من الامثلة لفهمها بشكل تام وكامل\n\nايضا راح تدرس Transportation problems وانا اعشق هذا النوع من الاسئلة لاني كما قلت اعتبرها الغاز\n\nمثال بسيط جدا :\n\nعندك 3 مناطق رئيسية ونريد ان نوصل اسلاك الكهرباء بينهم او سكة القطار او رحلات جوية , الخ بأقل تكلفة ممكنة\n\nمثلا اسعار التكلفة لتوصيل الكهرباء للمناطق هي كالتالي:\n\nمن الدمام الى الرياض = 15 الف\nمن الدمام الى جدة = 35 الف\nمن الرياض الى جدة = 20 الف\n\nمن خلال التكاليف في الاعلى نجد ان الافضل ان نبي المركز الرئيسي بالرياض ونوصل لجدة بتكلفة 20 الف + 15 الف للدمام = 35 الف مجموع التكلفة\n\nهذا المثال بسيط جدا جدا وهو فقط للتوضيح\n\nالمادة اعتبرها انا مهضومة و ممتعة وايضا تحتاج الى جهد وحل تمارين\n\nالكتاب المقرر اشوف انه مناسب بالرغم اني ماتعمقت فيه كثير\n\nصعوبة المادة: 7.5 من 10\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/2", "user": "user3193", "ts": 1339142008000, "tid": 120935, "pn": 2}}', 1339142008000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231859-ise303', 'stk-me_i10', 'ISE 303', 'info', '{"desc": "كورس حلو وممتع\nيحتاج بس براكتس ومتابعة اول بأول\n\nوتقدر تقول الكورس سهل الى حد كبير , عدى تشبتر 4 الي يبي له جهد اكبر من باقي التشباتر\n\nالكتاب احيانا شرحه يكون غير واضح خصوصا تشبتر 4 و تشبتر 5\nفأي درس ما تفهمه يمديك تلقاه مشروح بشكل كويس باليوتيوب\nخصوصا هالدكتور http://www.youtube.com/watch?v=a2QgdDk4Xjw\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/3", "user": "ME_I10", "ts": 1370359594000, "tid": 120935, "pn": 3}}', 1370359594000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320412-ise303', 'stk-user2352', 'ISE 303', 'info', '{"desc": "يطلق مصطلح “بحوث العمليات Operation Research” أو ما يطلق عليها أختصاراً “OR” على مجموعة الأساليب والطرق الكمية التحليلية التي تسعي إلى صياغة وتطوير نماذج للمشكلات العملية والمساعدة في عملية إتخاذ القرار بعد حساب متغيرات كل قرار (بديل) والتوصل إلى إختيار القرار الأمثل من بين البدائل المتاحة أو الأستخدامات المتنافسة بحيث يمكن تحقيق أعلى مستوى من العائد المتوقع أو تخفيض الوقت أو التكاليف إلى أدني مستوى ممكن …وغير ذلك من الأهداف المرجوة.\nوبإختصار تعتبر بحوث العمليات أدوات تحليل علمي منهجي للمشاكل التي تواجه منظمات الأعمال والمؤسسات الأقتصادية بما يمكن الإدارات من حل هذه المشاكل والتقليل من درجة المخاطرة أو حالات عدم التأكد المرافقة لبيئة الأعمال إلى أقصى حد ممكن ويرجع تسمية بحوث العمليات بهذا الإسم إلى العمليات الحربية التي كانت أولى المجالات التي استخدمت فيها، وإن كان تطبيقها اليوم قد تعدى المجال الحربي ليصل إلى آفاق جديدة ،مثل :المصانع ،المستشفيات ، تخطيط المدن، المواصلات\nأهمية إستخدام بحوث العمليات في الإدارة:إن زيادة حجم النشاط الذي تقوم به المنظمات الإدارية المختلفة ،وتزايد التعقيدات التي تتسم بها الإجراءات الإدارية، إضافة إلى إدراك الإدارة لمدي أهمية القرار الإداري السليم، مما ترتب عنه إنتشار إستعمال الأساليب الرياضية والإحصائية في مجالات الإدارة، ولاسيما إدارة الأعمال بشكل واسع في الآونة الأخيرة.\n\nإن إستخدام بحوث العمليات -الأساليب الكمية التحليلية- يساعد أولئك الذين يواجهون مشكلة إتخاذ القرارات الإدارية خاصة تلك التي تعتمد على عدد من الحقائق والمتغيرات المعقدة والمتداخلة مع بعضها. علاوة على ذلك…فإن إتباع تلك الأساليب الكمية يغطي حلولاً أفضل من تلك التي تنتج عن غيرها من الأساليب ،والتي تتطلب فروض محددة مبنية على إستنتاجات سليمة، ووضع المتغيرات في علاقات رياضية مناسبة ، ومن الأمثلة على هذه الأساليب :البرمجة الخطية-نظرية القرارات، تحليل شبكات الأعمال…وغيرها. وهذه الطرق تزود الإدارة بأدوات لحل المشاكل المستعصية في الإنتاج والتخزين والتمويل والنقل …إلخ ،كما تمكنها من تقييم السياسات البديلة للتشغيل والإستثمار ،وتساعدها في تحديد إحتياجات المنشأة في المدي الطويل. لكن -على الرغم من كل المزايا -فإن هذه الأساليب لا تخلو من بعض العيوب، ولعل من أهمها: إرتفاع تكاليف إستخدامها ،وكذلك إحتياجها إلى خبرات وقدرات علمية عالية للتعامل معها ،قد تتوافر وقد لا تتوافر في المشروع، كما أنها لا تصلح في حل المشاكل غير المحدودة المعالم، أو التي لا يمكن معالجة متغيراتها كمياً بالإضافة إلى كون الأساليب الرياضية لا تمثل الإجراءات الكاملة لصنع القرارات، وليست الأسلوب الوحيد المفيد دائما لحل المشاكل الإدارية ،وإنما تبقي للأساليب الأخرى قيمتها في كثير من المجالات.\nمنهج بحوث العمليات في إتخاذ القرارات:\nإن إتخاذ القرارات بإستخدام بحوث العمليات ،يستلزم المرور بالخطوات التالية:\n\n1. تعريف أو تحديد المشكلة.\n2. بناء النموذج الذي يمثل المشكلة قيد الدراسة.\n3. إختبار النموذج.\n4. حل النموذج.\n5. إختبار مدى مناسبة الحل.\n6 . تطبيق الحل.\n\nهذه الخطوات ليست منفصلة ،ولكنها متداخلة تماماً بمعني أنه قد يتم الأنتقال من أي خطوة إلى الخطوة السابقة أو اللاحقة لها وذلك بشكل متكرر حتى يتم التوصل لحل المشكلة المطروحة. تجدر الإشارة إلى أنه لا توجد قواعد أو أسس ثابتة في تنفيذ هذه الخطوات، إذا أستثنينا عملية حل النموذج ،حيث يتم إستخدام تقنية معروفة لحل النموذج كالسمبلكس مثلاَ ،أما الخطوات الأربع الأخرى …فإن تنفيذها يعتمد على عوامل مختلفة، مثل: نوع المشكلة موضع البحث وطبيعتها ،وأسلوب الباحث في التحليل…إلخ، من ناحية أخرى. فإن هذه الخطوات لا يتم الخوض فيها بمعرفة باحث العمليات وحده ،بل لابد من التعاون بينه، وبين المسؤولين عن الأنشطة حيث توجد هذه المشاكل، وهذا التعاون أو المشاركة بين الطرفين تستمد أهميتها من شيئين: الأول هو أن هؤلاء المسؤولين يعتبرون مصدراً للمعلومات، التي يعتمد عليها باحث العمليات في كل العمل الذي يقوم به بخصوص حل المشكلة ،والثاني أن هؤلاء المسؤولين هم الذين سيطبقون النتائج التي قد يتوصل إليها باحث العمليات في حله للمشكلة، وبالتالي لابد من ضرورة اشتراكهم في المراحل المختلفة لحلها.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/6", "user": "user2352", "ts": 1389995776000, "tid": 120935, "pn": 6}}', 1389995776000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450451-ise303', 'stk-fahad_2012', 'ISE 303', 'info', '{"desc": "الكورس مهم ومن اساسيات التخصص ويعتبر جزء من ise 421\nالكورس نوعاً ما متوسط الصعوبة ويعتمد عالدكتور اللي يدرسك المادة\nالمادة تحتاج دكتور يحل كثير ويشرح المادة بشكل مفصل مثل الدكتور الحبوبي\n\nجودة المقرر بشكل عام : ممتازة\n\nالمواضيع التي يغطيها المقرر : Formulation of LP models , Simplex Method , Transportation Model\n\nالكتاب المستخدم للمقرر : الكتاب واضح وجيد , لكن بعض الدكاترة قد يختلفون في طريقة الحل عن الكتاب مثل الدكتور الحبوبي\n\nالأسئلة والأمثلة المستخدمة في المقرر : مختلفة ومنوعة لكن والاختبارات قد تاخذ بعض الافكار\n\nالكورس يحتاج متابعه\n\nسيلبس المادة في المرفقات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/14", "user": "Fahad_2012", "ts": 1464245054000, "tid": 120935, "pn": 14}}', 1464245054000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1524126-ise303', 'stk-feras-mtn', 'ISE 303', 'info', '{"desc": "Term 192\n\nجودة المقرر بشكل عام\nممتاز ومهم جدا\n\nالمواضيع التي يغطيها المقرر\nCh2: Modeling with Linear Programming\nCh3: The Simplex Method and Sensitivity Analysis\nCh4: Duality and Post-Optimal Analysis\nCh5: Transportation Model and Its Variants\nCh6: Network Model\nCh8: Goal Programming\n\nالكتاب المستخدم للمقرر\nممتاز ويعطي امثلة واسئلة من الواقع … وانصح بسلايدات ياسر المغذوي\n\nمدى فائدته في الناحية التطبيقية\nمفيد ومن اهم مواد التخصص\n\nإضافات\nماودي اتكلم واتعمق في الاختبارات لانه خذيتها بترم النكبة 192 (كورونا الله يكفينا شره) وكان فيه لخبطة والغاء مياجر وتكثير كويزات … فعالعموم المادة كل ما اتدربت اكثر فيها بتتمكن منها اكثر وخصوصا في تشابتر 2 اللي عبارة عن Formulations (تشابتر يبيله جهد اكثر) + تشابتر 4 اللي اشوفه اصعب تشابتر وخصوصا جزئية الsinsitivity\n\nلكن تشابتر 5 وانت طالع جدا جدا سهل ولا تضيع درجات فيه … واذا شفت الدكتور ياسر المغذوي سجل عنده ذا الكورس وانت مغمض\nوبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/15", "user": "Feras-MTN", "ts": 1595497719000, "tid": 120935, "pn": 15}}', 1595497719000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527327-ise303', 'stk-guest', 'ISE 303', 'info', '{"desc": "Term 201-Online\nالاخ فارس والبقية غالبا ذكروا كل شي يخص المادة تقريبا فما يحتاج الزيادة والتكرار، بذكرعدة نقاط ان شاء الله تفيدك في دراسة هالمقرر\n\nقبل دراسة هالمادة كنت متخوف كثير من بسبب كلام بعض الشباب، لكن في النهاية اكتشفت انها مثل كورسات الماث مع بعض الأختلافات البسيطة، بشكل عام كل شابتر له بروسيجر وتمشي عليه ما يبغاله ابداع او ذكاء (باستثناء CH-2 & 8)، بالنسبة لي المادة اسهل بكثير من 315، 320 بشكل كبير لان مافيه كونسبت مجرد خطوات وتمشي عليها.\nاغلب الشباب متعقدين من هالمادة بسبب (CH-2) وه فعلا صعب ويحتاج ذكاء وتركيز واستيعاب، لان كل سؤال له طريقة حل مختلفه وبروسيجر معين عموما مع كثرة التدريب راح تتعود على الفكره وتنطلق، وصراحة بالنسبة لي كان هذا اجمل جزئية فالكتاب لانها بالضبط مثل الألغاز وانت تحاول تلقى الحل، عموما اذا جبت العيد فيه تقدر بسهولة تعوض فالجزئيات الثانية\nشابتر 8 مجرد تكمله ل شابتر 2 ومافيه شي جديد\nفيه شرح في قناة النادي في يوتيوب، الاخوان ما قصروا الشرح واضح وجميل (الرابط)\nفيه شروح مسجلة من كلاسات الدكتور ياسر المغذوي، اذا راعيها ما حذفها راح تحصلها (هنا)\nدعواتكم و بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/16", "user": "Guest", "ts": 1609096708000, "tid": 120935, "pn": 16}}', 1609096708000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1537216-ise303', 'stk-user12137', 'ISE 303', 'info', '{"desc": "T231\n\nجودة المقرر بشكل عام:\nممتع جدًا ومهم في تخصصنا\n\nالمواضيع التي يغطيها المقرر\nCh2: Modeling with Linear Programming\nيعلمك كيف تصيغ مشاكل العالم الواقعي على هيئة رياضية للحصول على الحل (فقط حالة الكونتينيوس واللينيار),ممتع جدا بس تشابتر صعب أمانة\nCh3: The Simplex Method and Sensitivity Analysis\nطريقة حل النموذج الرياضي الي توصلت له عبر السيمبلكس ميثود للحصول على الحل الأمثل وكيف تعدل عليه مع بقاء الحل أمثل,تشابتر وسط مستواه\nCh4: Duality and Post-Optimal Analysis\nالديوال تقدر تقول كأنه عكس الموديل الي عندك, والبوست اوبتيمال هو يعطيك تغير في النموذج الرياضي أو النتائج ويقولك شيك على حلك هل ما زال هو الحل الأمثل وقابل للتطبيق واذا ما هو الأمثل بتحاول توجده عبر طرق معينة, وهذا تشابتر متعب أمانة\nCh5: Transportation Model and Its Variants\nمن اسمها ترانسبورتيشن موديل وهذي تستعملها لما يكون عندك: مصدر (جرير,اكسترا), مستقبل (محلات الجوالات),عدد معين من المنتج(آيفون),تكلفة على نقل المنتج(الشحن) وفي حالات شبيهة بها يستعمل بها نفس الموديل (نونتراديشنوال ترانسبورتيشن موديل). تقدر تحلها عن طريق السمبلكس بس بيكون غير عملي ,فاستعمال الموديل الجديد (متحور سمبليكس) والطرق الموجودة بهذا التشابتر بتكون أكثر عملية , تشابتر سهل\nCh6: Network Model\nهذا التشابتر عملي أظن وأحسه مختلف شوي عن الباقي, لعله اسهلهم\nCh8: Goal Programming\nهذا تشابتر واقعي بس ما تطول فيه, القول بروجرامنج هو لما يكون في تضارب مصالح في الشروط الي حاطنها ,مثال توضيحي: (1-أريد أذاكر أقل من 10 دقائق يوميا ,2- أريد أحصل على A+ في كل المواد) فهنا في تضارب واضح في المصالح والي يعالج الاشكال هو القول بروجرامنج (تستعملها لما غالبا ما يكون أصلا في حل قابل للتطبيق فتحاول تعفط الشروط حسب ترتيب الأهمية الي وضعته أنت بحيث توجد حل قابل للتطبيق),تشابتر قصير سهل\n\nالكتاب المستخدم للمقرر:\nالسلايدات أحسها أفضل بشكل عام, خصوصا في توضيح طرق الحل والتسلسل للأفكار بشكل عام, لكن الكتاب جيد جدا يعتبر وصياغته ما هي جلفة علمية وإنما شوي مرحة وأحيانا تكون أفضل من السلايدات للكونسبت وللأمثلة الغير مطروحة في السلايدات\n\nمدى فائدته في الناحية التطبيقية:\nمفيد ومن اهم مواد التخصص\n\nإضافات:\nطريقة المذاكرة:\n-أركز مع دكتوري في الكلاس (الصوافي)\n-قبل المياجر أخلص فيديوهات ياسر المغذوي T201\n-أحل واجبات الصوافي (في مجموعة تكون مع 3 طلاب)\n-أحل كويزات, وكلاس تيستات المغذوي في نيبولا, والاولد اكزامز اذا موجود (موجودة هوموركات بعد لمن يريد)\nجبت B+\n\nأخطاء ارتكبتها:\n-ما كنت أذاكر زين للكويزات ولا أحل قبلها\n-ما شفت هيلب سشنز المغذوي بنيوبلا\n- ما انتبهت لملفات ومسائل المغذوي الا وقت بالفاينل\n-دائما أنكب حالي (في الميجر الاول نسيت احل آخر صفحة, الثاني فهمت سؤال ثقيل غلط وحليته بطريقة مختلفة, الفاينل نسيت الحاسبة)\n\nملاحظة: اضافوا شيء جديد هالترم (بونص 2.5 على المشاركة بالتييمز, بونص على IBL وهو أنه يعطيك حل جاهز وترويه كيف هو توصل لهالحل بالتفصيل وتجاوب على بعض الاسئلة)\n\nآفرج الميجر الاول: 17.88 من 25\nآفرج الميجر الثاني: حدود ال17.2 من 25\nآفرج الفاينل: ما أعلنوا بس عالي غالبا لأنه سهل الميتيريال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-303-operation-research-i/120935/18", "user": "user12137", "ts": 1704975609000, "tid": 120935, "pn": 18}}', 1704975609000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p600029-ise303', 'stk-ise-26', 'ISE 303', 'info', '{"desc": "Ise 303 lec mohammad al-habboubi\n\nise 323 lec muhammad addas\n\nise 325 lec m. Al-rougi\n\nالدكتور محمد الحبوبي لا تفوته عليك بـ 303 … من جد دكتور قمة في الروعه في شرحه\nومن آفضل الدكآتره اللي مروا علي بالقسم\n\nالدكتور محمد عداس درسني السمستر اللي راح 323 … وكآن تمام ومادته خفيفه وحلوه\nوقريدآته حلوه … واشوفه آحسن من السلآمه\n\nالدكتور مازن الروقي 325 … ما شاء الله كلآسه ممتع ودكتور ونآسه وكل شي فيه تمام\nوما يحتاج اقول لك عنه لانه معروف\n\nوبالنسبه للدكتورر الغامدي … انا صراحه ما قد درست عنده ولا اعرفه\nبس من كلآم النآس يقولون اي كورس معاه يكون كورس حفظ وكل شي تحفظه\n\nونفس الكلآم بالنسبه للدكتور طآهر … بس آحسه آخف من الغامدي\nولا انصح بطآهر بكورس 307 …\n\nبالتوفيق يارب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/093-101/87437/60", "user": "ISE-26", "ts": 1273057087000, "tid": 87437, "pn": 60}}', 1273057087000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p885548-ise303', 'stk-fond_of_you', 'ISE 303', 'srcU', '{"html": "وعليكم السلام … فيك تخصص يتكلم عن الموضوع هذا الي هو engineering management<br><br>http://www3.kfupm.edu.sa/cem/programs/cd<br><br>وفيه كورس اللي هو ISE 303<br><br>وفيه جزء من الproject management وهو يغطي تقريبا طريقتين اللي هي CPM و PERT 🙂<br><br>​<span data-fid=\"stk-f885548-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f885548-0": {"name": "Degree Plan.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110752/2", "user": "Fond_Of_You", "ts": 1313329776000, "tid": 110752, "pn": 2}}', 1313329776000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-es_engineer-ise303', 'stk-es_engineer', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f98290", "n": "Dr. Mohammad Al-Haboubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Operations Research ISE 303\n\nالتحضير : يحضر اول الكلاس وما يحب التأخير ويحب اللي يجلسون قدام\n\nطريقة الشرح : افضل طريقة شرح ممكن تتخيلها !! تحس انك في مدرسة ! رهيب ويحب يتأكد ان الجميع فاهمين ويحاول يحجر للي نايمين ومو منتبهين معه … ويحرصك انك تطبع السلايدات قبل لا تجي الكلاس عشان تسجل عليها نوتات وهو يشرح من السلايدات !!! لأنه قبل كان يخليهم يكتبون كل شي لكن الحين سهل عليهم\n\nيحمسك في الشرح خاصة لو كنت تجلس قدام ويخليك تشغل مخك وتفكر\nلكن مشكلته انه يجاوب اسئلة غبية ويضيع وقت الكلاس لكن يبي يفهم اي واحد مو فاهم ويجاوب جميع الاسئلة من الطلاب اثناء الشرح\n\nالكويزات : ما عنده كوزات في هالمادة !! اريح شي بالنسبة لي صراحة\n\nالمياجر: 3 مياجر كل واحد عليه 20% واحد صعب واحد سهل واحد نص ونص\nكلها نفس المياجر القديمة … كلم زملائك اللي اخذوا المادة معاه ويعلمونك وش بيجيب لكم بالضببببط\n\nالفاينلات : 25% عليه ونفس كلامي عن المياجر\n\nالقريد النهائي: A+ يستاهل اكثر\n\nالصوت: واضح\n\nإضافات :\nالدكتور حبوبي يحفظ الاسامي بسرعة !! ما شاء الله عليه يعرف الكلاس كله وينادي الجميع بأساميهم\nوانتبه تستهبل عليه ولا شي … شايب تراه ما يحب حركات النص كم واللف والدوران\n\nالدكتور محمد الحبوبي يبذل جهد كبيييييير في الشرح وخلال تواجده في الاوفس اور\nلا يفوتكم !!! واحد من عمالقة القسم بصراحة\nليته يدرس مواد اكثر\n\nالله يجزاك خير يا دكتور حبوبي وكانت تجربة جميلة معاك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779939-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-haboubi/98290/9", "user": "ES_Engineer", "ts": 1296527958000, "tid": 98290, "pn": 9}}]}', 1296527958000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-samt_2011-ise303', 'stk-samt_2011', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f98290", "n": "Dr. Mohammad Al-Haboubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nطريقة الشرح :\nالكويزات :\nالمياجر:\nالفاينلات :\nالقريد النهائي:\nالصوت:\nإضافات\n\nبسم الله الرحمن الرحيم\n\nاخذت معه ISE303\n\nالتحضير\nيحضر نهاية كل كلاس ولايرضى بالتاخير نهائيا, نصيحة لك اذا جيت يوم متاخر لاتفتح الباب لانه متشدد في هالنقطة مستحيل يدخلك لو يمر على وقت الكلاس دقيقة وحدة بس 🥊\n\nطريقة الشرح\nالدكتور الحبوبي من افضل دكاترة القسم اذا ماكن افضلهم, عنده قدرة عجيبه على افهام الطلاب بشكل ماتتصور يستخدم سلايداته للشرح, نصيحة اذا كنت تبحث عن فهم صح نزل الكورس معاه لكن اللي ينعاب عليه شي واحد وهو قلت الامثلة يعني تشوفه يجيب مثال واحد وبيمشي معاك طول الكورس, وفي الاختبارات ناكلها لانه مافيه امثلة كفاية علشان نتدرب, لكن للامانة شرحه كافي ومغطي لكل جوانب المنهج\n\nالكويزات\nمافيه\n\nالمياجر\nماكان يعطينا مياجر بس كان فيه عنده اقزامات بعد كل شبتر يعني تقريبا اربعه الى خمسة اقزامات ويكون عليها قريدك, القزامات كانت متوسطة الى صعبه لانه مايعطي امثلة كثير في الكلاس بيعطيك مثال واحد ال WINDOOR EXAMPLE وبيمشي عليه طول الكورس\n\nالفاينلات\nمتوسط الى صعب واتذكر انه كان شامل المنهج كامل جاب سوال صح وخطا اذا كنت مركز معاه بالكلاسات راح تحله وانت مغمض 🤣 وثلاث اساله مسائل واحد على القول بروقرمنق وواحد فورميليشن وواحد على SENSITIVITY ANALYSIS الفاينل بالمجمل كان طويل ولازم قبل لاتدخل تكون متدرب على الفورميلشين علشان لاتاخذ وقت طويل وانت تحل\n\nالصوت\nلصوت واضح والاكسنت حقه ممتاز جدا\n\nاضافات\nالدكتور الحبوبي من افضل الدكاترة اللي مرو علي من ناحية الشرح لكن على قد الشرح توقع مياجرة بتجيك, الدكتور له مشاريع كثيرة واتوقع انه تبع قسم الكوالتي اللي بالجامعه عنده مشروع الحج من اضخم المشارع اللي سواها لكنه ماتنفذ الى حد الان فكرة المشروع انه كيف يقلل الFLOW حق الحجاج مشروع كبير وضخم جدا\n\nانصح فيه وانت مغمض لاي كورس ينزله خصوصا الكورسات ليفل تو وثري علشان تبدا التاسيس صح 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1344829-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-haboubi/98290/26", "user": "Samt_2011", "ts": 1395840704000, "tid": 98290, "pn": 26}}]}', 1395840704000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahad_2012-ise303', 'stk-fahad_2012', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f98290", "n": "Dr. Mohammad Al-Haboubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 152\nISE 303 & ISE 405\n\nالتحضير : في نهاية كل كلاس , والحضور عليه 5% والغياب على حسب سؤالي له بين النص درجه والدرجه\nطريقة الشرح : من السلايدات ويحل عالسبورة , جودة السلايدات نوعاً ما غير جيده بمعنى اذا ما انتبهت معه بالكلاس مارح تكون واضحه بالنسبة لك\nالكويزات : لا يوجد\n\nالمياجر: 405 كان ميدتيرم وفاينل , 303 اربعه كلاس تستات كل واحد ب 15%\nصعوبتها نوعاً ما متوسط مرتفع , مافيه شي مباشر و الافكار مختلفه شوي عن السلايدات والشرح\n\nالفاينلات : اسهل من الميدتيرم والكلاس تيست , ولكن ليست سهلة\n\nالقريد النهائي: B\n\nالصوت: واضح جداً\n\nإضافات : الدكتور محمد الحبوبي من اقدم واشهر دكاترة القسم وله ابحاث واوراق منشوره كثيره وخبره عاليه\nورح تستفيد من خبرته وشرحه للمواد المهمة التخصص مثل الـ 405\nالدكتور شرحه واضح جداً ويهتم بالطلاب\nتصحيح الدكتور شديييد جداً وصعب جداً انه يزيدك\nوينقص عليك اذا كان حلك غير واضح او نسيت شيء بسيط\nصعب تاخذ عنده قريد عالي بشكل عام بحكم ان اغلبية واكثر الطلاب قريداتهم بين C والـ B\n\nانصح انك تاخذ معه الكورسات المهمة بالتخصص مثل الـ 405\nولكن ما انصح فيه اذا كان يهمك القريد فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450428-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-haboubi/98290/29", "user": "Fahad_2012", "ts": 1464234613000, "tid": 98290, "pn": 29}}]}', 1464234613000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fond_of_you-ise303', 'stk-fond_of_you', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f98650", "n": "Dr. Malick Ndiaye", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ise 303 -101\n\nالتحضير : يحضر اغلب الاحيان … يحفظ الطلاب بسرعة …\n\nطريقة الشرح : جيدة بس الاكسنت بعض الاحيان تخرب\nالكويزات : سهالات\nالمياجر: متوسطة\nالفاينلات : نشوف\nالقريد النهائي: يقولون الشباب قريدات الرجل مرة …\n\nلكن بنهاية الترم نعطيك الكلام الصحيح 🙂\n\nالصوت: واضح\n\nإضافات : دكتور مرة فلة ومرح كلاسه ما تحس بملل ابد ابد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p745596-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-malick-ndiaye/98650/3", "user": "Fond_Of_You", "ts": 1292578682000, "tid": 98650, "pn": 3}}]}', 1292578682000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2536-ise303', 'stk-user2536', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f98650", "n": "Dr. Malick Ndiaye", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ise 303\n\nالتحضير : يحضر عشوائي … يوم ويومين لأ\n\nطريقة الشرح : يفتح السلايد بس شكل ويشرح من راسه ويوزع اوراق مسائل ممتازة وشرحه عادي جدا لكن ممتع\n\nالكويزات : متوسطة … بعضها يميل للصعوبة …\n\nالمياجر: متوسطة … لكن توزيع الدرجات سيء جدا\n\nالفاينلات : متوسط …\n\nالقريد النهائي: أعطيه B +\n\nالصوت: واضح\n\nإضافات : كلاسه ممتع جدا ومدري كيف يمر الوقت … اسئلته ماهي على قد شرحه لان الشرح لك عليه بقوة والاسئلة فيها صعوبة دايم لكن المادة حلوة جدا معاه … من أسرع وأخف الكلاسات اللي اخذتها في الجامعة رغم انه طويل … خفيف دم ولازم كل كلاس تضحك معاه … مزاجي بشكل عجيب … أنصح فيه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852427-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-malick-ndiaye/98650/12", "user": "user2536", "ts": 1307995543000, "tid": 98650, "pn": 12}}]}', 1307995543000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ise303', 'stk-guest', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f118717", "n": "Dr. Yasser Al-Moghathawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 201-ISE-303- online\nالتحضير : آلي عن طريق مايكروسوفت تيمز\nطريقة الشرح : عن طريق السلايدات ويستخدم شرح قلم الكتروني عشان يحل بعض المسائل ويوضح النقاط المبهمة\nالكويزات : صعبة تحتاج استعداد كبير لكن الفكرة تكون واضحة لكن السؤال صعب + يعطيك وقت كافي تحل عكس بعض الدكاتره يعطونك 5 دقايق، افرج الكويات كان 5 من عشره فبعدها عطانا كويزيت سهله عشان يرفع الافرج.\nالمياجر: الترم هذا ما كان فيه مياجر 6 تستات كل واحد يقول انا اصعب، اخر اثنين نسبيا كانت سهلة، والتستات كانت كومن يعني كل دكتور يحط سؤال\nالفاينلات : مافيه، كان فايه اورال تست وباقي ما عطانا الدرجات لكن اسئلته مش سهله ومش صعبة وتتكلم عن الكونسبت بشكل عام.\nالقريد النهائي: زوين يمشي حالوه، ما عندي مشكله انزل عنده ماده ثانية\nالصوت: انجليزي سعودي واضح وغالبا الشرح بالإنجليزي.\nإضافات : الدكتور حبيب ومتعاون فالأوفس اورز لكن وقت الكلاس ما ادري ليش يتغير، يبغاك تتفاعل معاه فالشرح و على كل سؤال يطلب من الجميع انه يشارك، ماعند مشكلة انه يوقف الشرح عشان يحشر للي ما شاركوا\nالدكتور يتأخر في التصحيح فالكويزات والتستات(غالبا لان كل دكتور يصحح سؤاله)\nالدكتور ما طلب بروجكت + كان متعاون في تأجيل الكويزات و الهوموركات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527325-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yasser-al-moghathawi/118717/5", "user": "Guest", "ts": 1609089752000, "tid": 118717, "pn": 5}}]}', 1609089752000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise303', 'stk-bader_alqahtani', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f118717", "n": "Dr. Yasser Al-Moghathawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 201-ise303 Online\n\nالتحضير: يحضر من برنامج تيمز و مرات يسال بشكل عشوائي مو كثير عشان يعرف من حاضر يعني لو نادا عليك و سالك و ما رديت يحط لك غياب\nالشرح :يشرح على السلايدات الخاصة فيه و يحاول يوضح النقاط المهمة بس مرات ما يحل ف يسبب صعوبة في انك تفهم و يجيب امثلة شبه محلولة و يحلها معك فلما تروح تحاول تذاكر او تحل تحس انك ضايع ما تدري من وين تبدا و مرات يقاطع الشرح ب انه يسال الطلاب او يصير مشاركات تسبب انك تتشتت ذي العيوب الي شفتها في شرحه ان يسال و ما يحل كثير\nالكوزات: مستواها اصعب من التست يبيلك تكون مذاكر زييين و متدرب على اسالة كثير هو حاط رفرنسيس في السيلابوس تقدر تدور عالكتب و تسوي براكتس لان مرات كتاب ٣٠٣ امثلته تكون غريبة و ما تنفع كاسألة تتدرب عليها\nالتصحيح : الدكتور مرة حقاني و يدة ثقيلة في التصحيح مرة بالنانو التصحيح الا في الاخير حسيته تهاون معنا\nالاورال : اسالته كانت افرج لكن يحاول يضيعك و ما تدري على اي اساس الجواب صح اذكر عطيته جواب صح و قال مش ذا الجواب الي ابيه بالرغم من انه صح\n\nالقريدات: يعطيك حقك بالضبط ما يظلمك\n\nملاحظة : ك مدرس اشوفه جيد صراحة مش التوب ولا السيء لو عدل كذا مشكلة عنده ب اعتبره الافضل و جدا متعاون في الاوفيس اور و اخلاق لكن اذا جا الكلاس يتغير و مرات يجي منفس عموما انصح فيه في مادة ٣٠٣ +الدكتور احسه يساعد الطلاب عن طريق الهوموركات و الباركتس بروبلمز الي يرفعها جدا فادوني عشان افهم اكثر عموما اذا بتشد حيلك معه انصح فيه لان هو الافضل في مادة ٣٠٣", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527642-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yasser-al-moghathawi/118717/6", "user": "Bader_Alqahtani", "ts": 1609888975000, "tid": 118717, "pn": 6}}]}', 1609888975000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zad-ise303', 'stk-zad', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f118717", "n": "Dr. Yasser Al-Moghathawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE303- T221\nالتحضير: يحضر بالاسم نهاية المحاضرة\nالشرح : شرحه ممتاز لكل الأفكار\nالكوزات: متوسط\nالتصحيح : فيه اختلاف في التصحيح بين الطلاب مرة يمشي ومرة يدقق لكن بشكل عام حقاني\nالصوت: واضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536499-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yasser-al-moghathawi/118717/7", "user": "ZAD", "ts": 1679077726000, "tid": 118717, "pn": 7}}]}', 1679077726000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-ise303', 'stk-user2352', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f147064", "n": "Dr. Abdul Qadar Kara", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "باختصار مع هذا الدكتور ركز على الأمثلة ومسائل hw وحل جميع اسئلة SELF TEST بنهاية كل شابتر\nمع اغلب مسائل الكتاب ولا تغيب كثير وسلم جميع HW واغلب اختباراته ما تخرج من مسائل الكتاب مع تغيير الارقام\nوالتصحيح والقريد يعطيك حقك بالضبط ويمكن عيبه اختباراته طويلة شوي خاصة في 307+303\n\nطلاب ISE-303 فيه نوتة من تجميعي تحتوي على حلول مسائل هوموركات وكويزات الدكتور KARA\nمع مسائل اخرى مهمة غالبا شبيهه جدا باختبارات الدكتور نوتة صانع القرار لكل شابتر\nتجدونها في تصوير الجمعية بجوار عمارة 834", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1426643-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-qadar-kara/147064/12", "user": "user2352", "ts": 1441026709000, "tid": 147064, "pn": 12}}]}', 1441026709000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_ali_20-ise303', 'stk-abu_ali_20', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f147064", "n": "Dr. Abdul Qadar Kara", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Tern:151\nISE303\nالتحضير : يحضر دائما آخر المحاضرة وكثير يأخرنا من دقيقتين الى خمس دقايق\nطريقة الشرح : شرح جيد ، المادة تفهمها مع حل المسائل ، ممكن اذا جا يشرح الكونسبت ما تفهم عليه ، لكن اذا حل مسائل تفهم ،\nلا تتردد تسأله أي سؤال حتى لو تشوف انه سؤال بديهي , لأنه راح يجاوب عليك ويشرح لك لين ما تفهم\nالكويزات : سهلة جدا وما تطلع من الهموركات\nالمياجر: متوسطة ولكن تحتاج ممارسة … لا مجال للتفكير في وقت الاختبار … لازم تدرب وتحل وتخطأ وتصحح أخطائك في وقت المذاكرة… الوقت كان هو المشكلة الأكبر في اختبارت الدكتور …\n\n**( ملاحظة : الترم الماضي كان الدكتور يضع المياجر … الترم هذا والله العالم المياجر والفانيلات كومون )**الفاينلات : مثل المياجر ولكن كان الفاينل كومون\nالقريد النهائي: +B\nالصوت:واضح ولكن سريع\nإضافات: الدكتور طيب ومحترم … لكنه يهلك في الهموركات … تقريبا عطانا 10 هوموركات …\nفي البداية كانت الهموركات طويلة … بعدين صارت أقصر …\nتنفعك في المياجر بيحث انها تقريبا شاملة المنهج كامل …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1439884-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-qadar-kara/147064/15", "user": "ABU_ALI_20", "ts": 1453287976000, "tid": 147064, "pn": 15}}]}', 1453287976000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-ise303', 'stk-mkd', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f147064", "n": "Dr. Abdul Qadar Kara", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر والمادة: ISE 303 – Term 171\n\nالتعامل: مقبول، شخصيا ما كنت اشوفه جيد تحت شخصيا خطين ، ممكن عادي تسال سؤال ويعطيك نظرة اللي وش تبي بالحياة عليك وعلى غيرك. لما تروح الاوفيس فجاة تلقاه حبيب أتوقع انه من النوع اللي يبي يفرض نفسه بالكلاس فيعطيها وضعية الشديد لكن بينك وبينه بالاوفيس يقلب حبّي وتلقاه يشرح لك ويطول على أي شي انت تبيه وممكن يفتح سالفة مالها دخل مرة ويكملها معك\n\nالصوت: عالي وواضح تسمعه لو ايش ما شاء الله المشكلة كانت بالاكسنت والكلام السريع ، اكسنت الدول الاسيوية الهند باكستان وغيرهم ولكن يتكلم بسرعة بسرعة ما ادري ليه ، الشرح جيد كنت اشوفه والاكسنت ممكن تنبلع لكن السرعة بالكلام اشوفها ماثرة بشكل كبير، حاول تحضر معه كلاس واحد وشف الوضع جاز لك روح ما جاز لك لا تنكب عمرك وشف لك صرفة\n\nالشرح: لعلي دمجته مع الصوت بالغلط\n\nالتحضير: يوميا بداية الكلاس وشديد بالتحضير من الاخر\n\nالتصحيح: على حقك بالملي وممكن يعطيك اقل من حقك لو ما شاف ان حجتك مقنعة انه يعطيك اللي انت تستاهله\n\nالمياجر والفاينل (الاختبارات بشكل عام): وسط وممكن التصحيح يخليها صعبة\n\nإضافات: ميزته يعطي هومووركات مهمة وبشكل مستمر وبيهلك طول السمستر لكن ميزتها تدربك عالمياجر والفاينلات بشكل كبييير جدا ، قله يعطيكم السلوشن لكل هومورك لانها مهمة مهمة مهمة\n\nكويزاته القديمة تلقونها بالزلط محلولة من كم طالب لازم تمر عليها قبل أي كويز يجيكم ، ذاكر وخلص امورك وبعدين حلها اخر شي.\n\nحل أسئلة الكتاب لا تنسى جدا مهمة لأي شابتر في 303 لكن قبل لا تحل حاول تخليه يشوف الأسئلة\n\nبعضها مستواها ادفانس مرة وبعضها أساسا ماهي مطلوبة منكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504898-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdul-qadar-kara/147064/18", "user": "MKD", "ts": 1547472814000, "tid": 147064, "pn": 18}}]}', 1547472814000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ise303', 'stk-user12137', 'ISE 303', 'doc', '{"docs": [{"id": "stk-dr-f176912", "n": "Dr. Omar Alsawafy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE303-T231\n\nالتحضير : في نهاية كل محاضرة، ويحضر عن طريق الباركود بس ينتبه للي يتأخروا بشكل كبير أو متكرر ويحذرهم.\n\nطريقة الشرح : في البداية يعطيك مراجعة للدرس السابق، وبعدها يفتح السلايدات ويشرح منها. الدكتور متمكن من المادة وتحسه مستانس وهو يشرحها, وشرحه بشكل عام شامل لكل ما سيأتي في الاختبارات وجدا ممتاز ويغنيك عن اي مصدر آخر.\n\nالكويزات :صعبة شوي لأن الوقت قليل وأسئلته واجد ويكون مركز على الكونسبت بالذات “البايندنق كونسترينت” هذي عشقه.\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: جدا ممتاز وواضح\n\nإضافات :\n-لا يخرشك تقييم النجوم الي فوق الدكتور ممتاز\n-الدكتور ينكت ويمديك تنكت وياه ويفهم عليك ما هو جلف, ويحب يلعب كول اوف دوتي عدل شبابي\n-الدكتور طيب ومتساعد ومهتم بشدة أن كل طالب يفهم, واذا بتجيه الاوفس اور كلمه قبلها عبر التييمز عشان تحجز لك وقت لأن دايم مزحوم ألاحظ (إذا حجزت موعد معاه حتى لو خلص الاوفس اور من الزحمة بيقعد بعد الاوفس اور معاك لأنك حجزت من قبل ومتفق معاه لين بكرة لو تبغى)\n- العيب الي ذكره الاخ MZD اشوف أكثر من واحد طراه وتكرر بس ما لاحظته شخصيا (ممكن لأن سكشننا اسئلته قليلة وعدده قليل), بس لاحظت أنه شوي يتلخبط في الكلام لما تسأله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537217-ise303", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/omar-alsawafy/176912/6", "user": "user12137", "ts": 1704976561000, "tid": 176912, "pn": 6}}]}', 1704976561000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
